export interface ContentFiles {
  lessons: Record<string, string>;
  quizzes: Record<string, string>;
  glossary: string;
}

/** The text of `generated.ts`: the content files as strings, so the app can load them without reading a disk. */
export function generatedSource(files: ContentFiles): string {
  const dict = (r: Record<string, string>): string =>
    `{\n${Object.keys(r)
      .sort()
      .map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(r[k])},`)
      .join('\n')}\n}`;
  return [
    '// Generated by `pnpm content:build` from packages/content/lessons, quizzes and glossary.md. Do not edit by hand.',
    `export const LESSON_FILES: Record<string, string> = ${dict(files.lessons)};`,
    `export const QUIZ_FILES: Record<string, string> = ${dict(files.quizzes)};`,
    `export const GLOSSARY_FILE = ${JSON.stringify(files.glossary)};`,
    '',
  ].join('\n');
}
